import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { blockWalls, refusals } from "../src/hooks.js";

const recorded = (name: string) => JSON.parse(readFileSync(new URL(`./inputs/${name}.json`, import.meta.url), "utf8"));
const signal = new AbortController().signal;
const decide = async (name: string) => {
  const out = await blockWalls(recorded(name), recorded(name).tool_use_id, { signal });
  return (out as { hookSpecificOutput?: { permissionDecision?: string } }).hookSpecificOutput?.permissionDecision ?? "no opinion";
};

test("an edit to a CI workflow is denied and recorded", async () => {
  assert.equal(await decide("edit-workflow"), "deny");
  assert.equal(refusals.at(-1)?.target, "/work/fcp/.github/workflows/frontend-ci.yml");
});

test("terragrunt apply is denied", async () => {
  assert.equal(await decide("bash-apply"), "deny");
});

test("an edit to a normal component is left to the permission rules", async () => {
  assert.equal(await decide("edit-component"), "no opinion");
});
